INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ヤマト", -416.5, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", "2024/10/31 12:00:00", 130011, 3001, 3001100, 0.0, 1, 2.1, 100, 2, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ヤマト", -416.5, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", "2024/10/31 12:00:00", 130011, 3001, 3001101, 0.0, 4, 5.68, 101, 2, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ヤマト", -416.5, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", "2024/10/31 12:00:00", 130011, 3001, 3001102, 0.0, 1, 0.0, 102, 1, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", -416.5, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", "2024/10/31 12:00:00", 130211, 3002, 3002100, 0.0, 1, 0.0, 100, 1, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", -416.5, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", "2024/10/31 12:00:00", 130211, 3002, 3002101, 0.0, 1, 0.0, 101, 1, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", -416.5, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", "2024/10/31 12:00:00", 130211, 3002, 3002102, 0.0, 5, 8.53, 102, 2, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", -416.5, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", "2024/10/31 12:00:00", 130211, 3002, 3002103, 0.0, 7, 5.67, 103, 1, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", -416.5, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", "2024/10/31 12:00:00", 130211, 3002, 3002104, 0.0, 1, 0.0, 104, 1, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", -416.5, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", "2024/10/31 12:00:00", 130211, 3004, 3002300, 0.0, 3, 0.0, 300, 3, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", -416.5, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", "2024/10/31 12:00:00", 130211, 3005, 3002400, 0.0, 7, 0.0, 301, 7, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", -416.5, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", "2024/10/31 12:00:00", 130211, 3003, 3003200, 0.0, 2, 4.4, 200, 1, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", -416.5, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", "2024/10/31 12:00:00", 130211, 3003, 3003201, 0.0, 7, 0.0, 201, 7, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("フブキ", -416.5, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", "2024/10/31 12:00:00", 130211, 3003, 3003202, 0.0, 1, 5.6, 202, 2, "2030/01/01 14:59:59");
